class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        if k == 1:
            return sum(nums)

        if k > len(nums):
            return 0

        max_sum = float('-inf')
        current_sum = 0
        count = 0

        # Iterate through the array
        for num in nums:
            current_sum += num
            count += 1

            # If the current subarray length is divisible by k, update the max sum
            if count % k == 0:
                max_sum = max(max_sum, current_sum)

            # Reset current sum and count when starting a new subarray
            current_sum = 0
            count = 1

        return max_sum
