from typing import List

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        if not nums:
            return 0

        n = len(nums)
        # Sort the array to easily process elements
        nums.sort()

        # dp[i] will store the length of the longest non-increasing subsequence ending at index i
        dp = [1] * n

        # For each element, we check all elements to its left that are smaller than current element
        # and update dp[i] based on the previous dp value
        for i in range(1, n):
            for j in range(i - 1, -1, -1):
                if nums[i] > nums[j]:
                    dp[i] = max(dp[i], dp[j] + 1)

        # The length of the longest non-increasing subsequence is the maximum value in dp
        return max(dp)
